{"command":"cat <<'EOF' > src/main.rs
use clap::Parser;
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Clear, List, ListItem, ListState, Paragraph, Wrap},
    Frame, Terminal,
};
use std::{
    error::Error,
    fs,
    io,
    path::{Path, PathBuf},
};
use walkdir::WalkDir;
use regex::RegexBuilder;

#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    #[arg(short = 'p', long, default_value = ".")]
    project_root: PathBuf,
}

#[derive(Copy, Clone, PartialEq, Debug)]
enum SearchMode {
    Simple,
    MatchCase,
    MatchWholeWord,
    MatchCaseWholeWord,
    Regex,
}

impl SearchMode {
    fn next(self) -> Self {
        match self {
            SearchMode::Simple => SearchMode::MatchCase,
            SearchMode::MatchCase => SearchMode::MatchWholeWord,
            SearchMode::MatchWholeWord => SearchMode::MatchCaseWholeWord,
            SearchMode::MatchCaseWholeWord => SearchMode::Regex,
            SearchMode::Regex => SearchMode::Simple,
        }
    }
    fn label(self) -> &'static str {
        match self {
            SearchMode::Simple => "Simple",
            SearchMode::MatchCase => "Match Case",
            SearchMode::MatchWholeWord => "Match Whole Word",
            SearchMode::MatchCaseWholeWord => "Match Case Whole Word",
            SearchMode::Regex => "Regex",
        }
    }
}

#[derive(Copy, Clone, PartialEq, Debug)]
enum ReplaceMode {
    Simple,
    PreserveCase,
    DeleteLine,
}

impl ReplaceMode {
    fn next(self) -> Self {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }
    fn label(self) -> &'static str {
        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }
}

#[derive(Debug, Clone)]
struct Match {
    line_number: usize,
    line_content: String,
    start: usize,
    end: usize,
}

#[derive(Debug, Clone)]
struct FileMatches {
    path: PathBuf,
    matches: Vec<Match>,
}

enum Pane {
    Search,
    Replace,
    ResultList,
}

struct App {
    project_root: PathBuf,
    search_text: String,
    replace_text: String,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
    focused_pane: Pane,
    file_matches: Vec<FileMatches>,
    list_state: ListState,
    expanded: bool,
    expanded_match_index: usize,
    notification: Option<String>,
}

impl App {
    fn new(project_root: PathBuf) -> App {
        App {
            project_root,
            search_text: String::new(),
            replace_text: String::new(),
            search_mode: SearchMode::Simple,
            replace_mode: ReplaceMode::Simple,
            focused_pane: Pane::Search,
            file_matches: Vec::new(),
            list_state: ListState::default(),
            expanded: false,
            expanded_match_index: 0,
            notification: None,
        }
    }

    fn update_search(&mut self) {
        if self.search_text.is_empty() {
            self.file_matches.clear();
            self.list_state.select(None);
            return;
        }

        let mut results = Vec::new();
        let walk = WalkDir::new(&self.project_root).into_iter().filter_entry(|e| {
            !e.file_name().to_str().map(|s| s.starts_with('.')).unwrap_or(false)
        });

        for entry in walk.filter_map(|e| e.ok()) {
            if entry.file_type().is_file() {
                if let Ok(content) = fs::read_to_string(entry.path()) {
                    let mut matches = Vec::new();
                    for (i, line) in content.lines().enumerate() {
                        let line_matches = self.find_matches(line);
                        for (start, end) in line_matches {
                            matches.push(Match {
                                line_number: i + 1,
                                line_content: line.to_string(),
                                start,
                                end,
                            });
                        }
                    }
                    if !matches.is_empty() {
                        results.push(FileMatches {
                            path: entry.path().strip_prefix(&self.project_root).unwrap_or(entry.path()).to_path_buf(),
                            matches,
                        });
                    }
                }
            }
        }
        self.file_matches = results;
        if self.list_state.selected().is_none() && !self.file_matches.is_empty() {
            self.list_state.select(Some(0));
        }
    }

    fn find_matches(&self, line: &str) -> Vec<(usize, usize)> {
        let mut results = Vec::new();
        match self.search_mode {
            SearchMode::Simple | SearchMode::MatchCase | SearchMode::MatchWholeWord | SearchMode::MatchCaseWholeWord => {
                let case_sensitive = matches!(self.search_mode, SearchMode::MatchCase | SearchMode::MatchCaseWholeWord);
                let whole_word = matches!(self.search_mode, SearchMode::MatchWholeWord | SearchMode::MatchCaseWholeWord);

                let search_pattern = if case_sensitive { self.search_text.clone() } else { self.search_text.to_lowercase() };
                let target_line = if case_sensitive { line.to_string() } else { line.to_lowercase() };

                let mut start = 0;
                while let Some(pos) = target_line[start..].find(&search_pattern) {
                    let actual_start = start + pos;
                    let actual_end = actual_start + search_pattern.len();

                    let mut is_match = true;
                    if whole_word {
                        if actual_start > 0 {
                            let prev_char = line.chars().nth(actual_start - 1).unwrap_or(' ');
                            if prev_char.is_alphanumeric() || prev_char == '_' {
                                is_match = false;
                            }
                        }
                        if actual_end < line.len() {
                            let next_char = line.chars().nth(actual_end).unwrap_or(' ');
                            if next_char.is_alphanumeric() || next_char == '_' {
                                is_match = false;
                            }
                        }
                    }

                    if is_match {
                        results.push((actual_start, actual_end));
                    }
                    start = actual_end;
                    if search_pattern.is_empty() { break; }
                }
            }
            SearchMode::Regex => {
                if let Ok(re) = RegexBuilder::new(&self.search_text).case_insensitive(true).build() {
                    for m in re.find_iter(line) {
                        results.push((m.start(), m.end()));
                    }
                }
            }
        }
        results
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let args = Args::parse();
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(args.project_root);
    let res = run_app(&mut terminal, app);

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        println!("{:?}", err);
    }

    Ok(())
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, mut app: App) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui(f, &mut app))?;

        if let Event::Key(key) = event::read()? {
            match key.code {
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return Ok(()),
                KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => return Ok(()),
                KeyCode::Tab => {
                    app.focused_pane = match app.focused_pane {
                        Pane::Search => Pane::Replace,
                        Pane::Replace => Pane::ResultList,
                        Pane::ResultList => Pane::Search,
                    };
                }
                KeyCode::Char(c) => {
                    match app.focused_pane {
                        Pane::Search => {
                            app.search_text.push(c);
                            app.update_search();
                        }
                        Pane::Replace => {
                            app.replace_text.push(c);
                        }
                        Pane::ResultList => {
                            if c == 'k' || c == 'j' {
                                // Handle navigation
                            }
                        }
                    }
                }
                KeyCode::Backspace => {
                    match app.focused_pane {
                        Pane::Search => {
                            app.search_text.pop();
                            app.update_search();
                        }
                        Pane::Replace => {
                            app.replace_text.pop();
                        }
                        _ => {}
                    }
                }
                _ => {}
            }
        }
    }
}

fn ui(f: &mut Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(30), Constraint::Percentage(70)].as_ref())
        .split(f.size());

    let left_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Min(0),
        ].as_ref())
        .split(chunks[0]);

    // Search box
    let search_block = Block::default()
        .borders(Borders::ALL)
        .title(format!("Search [{}]", app.search_mode.label()))
        .border_style(if matches!(app.focused_pane, Pane::Search) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    let search_para = Paragraph::new(app.search_text.as_str()).block(search_block);
    f.render_widget(search_para, left_chunks[0]);

    // Replace box
    let replace_block = Block::default()
        .borders(Borders::ALL)
        .title(format!("Replace [{}]", app.replace_mode.label()))
        .border_style(if matches!(app.focused_pane, Pane::Replace) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    let replace_para = Paragraph::new(app.replace_text.as_str()).block(replace_block);
    f.render_widget(replace_para, left_chunks[1]);

    // Result List
    let items: Vec<ListItem> = app.file_matches.iter().map(|fm| {
        ListItem::new(format!("{} ({})", fm.path.display(), fm.matches.len()))
    }).collect();
    let list_block = Block::default()
        .borders(Borders::ALL)
        .title("Result List")
        .border_style(if matches!(app.focused_pane, Pane::ResultList) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    let list = List::new(items).block(list_block).highlight_style(Style::default().bg(Color::Blue));
    f.render_stateful_widget(list, left_chunks[2], &mut app.list_state);

    // Preview
    let preview_block = Block::default()
        .borders(Borders::ALL)
        .title("Preview")
        .border_style(Style::default().fg(Color::Green));
    f.render_widget(preview_block, chunks[1]);
}
EOF
"}

