        let mut last_end = 0;
        for (start, end) in matches {
            new_line.push_str(&line[last_end..start]);
            let original = &line[start..end];
            let replacement = self.get_replacement(original);
            new_line.push_str(&replacement);
            last_end = end;
        }
        new_line.push_str(&line[last_end..]);
