                                        app.match_index = 0;
                                    } else {
                                        app.match_index += 1;
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                    KeyCode::Char('r') => {
                        if !app.file_matches.is_empty() {
                            if app.expanded {
                                if let Some(selected) = app.list_state.selected() {
                                    let fm = &app.file_matches[selected];
                                    let mat = &fm.matches[app.match_index];
                                    let full_path = app.project_root.join(&fm.path);
                                    let content = fs::read_to_string(&full_path).unwrap();
                                    let mut lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
                                    let line_idx = mat.line_number - 1;
                                    if matches!(app.replace_mode, ReplaceMode::DeleteLine) {
                                        lines.remove(line_idx);
                                    } else {
                                        lines[line_idx] = app.replace_line(&lines[line_idx]);
                                    }
                                    let _ = fs::write(full_path, lines.join("\n") + if content.ends_with('\n') { "\n" } else { "" });
                                    app.update_search();
                                    app.set_notification("Line replacement completed successfully");
                                }
                            } else {
                                if let Some(selected) = app.list_state.selected() {
                                    app.replace_in_file(&app.file_matches[selected].path.clone());
                                    app.update_search();
                                    app.set_notification("File replacement completed successfully");
                                }
                            }
                        }
                    }
                    KeyCode::Char(c) => {
                        match app.focused_pane {
                            Pane::Search => { app.search_text.push(c); app.update_search(); }
                            Pane::Replace => { app.replace_text.push(c); }
                            _ => {}
                        }
                    }
                    KeyCode::Backspace => {
                        match app.focused_pane {
                            Pane::Search => { app.search_text.pop(); app.update_search(); }
                            Pane::Replace => { app.replace_text.pop(); }
                            _ => {}
                        }
                    }
                    KeyCode::Esc => {
                        if app.expanded {
                            app.expanded = false;
                            app.focused_pane = Pane::ResultList;
                        }
                    }
                    _ => {}
                }
            }
        }
    }
}

fn ui(f: &mut Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(30), Constraint::Percentage(70)].as_ref())
        .split(f.size());

    let left_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Min(0),
        ].as_ref())
        .split(chunks[0]);

    // Search box
    let search_block = Block::default()
        .borders(Borders::ALL)
        .title(format!("Search [{}]", app.search_mode.label()))
        .border_style(if matches!(app.focused_pane, Pane::Search) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    f.render_widget(Paragraph::new(app.search_text.as_str()).block(search_block), left_chunks[0]);

    // Replace box
    let replace_block = Block::default()
        .borders(Borders::ALL)
        .title(format!("Replace [{}]", app.replace_mode.label()))
        .border_style(if matches!(app.focused_pane, Pane::Replace) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    let replace_content = if matches!(app.replace_mode, ReplaceMode::DeleteLine) { "[Entire line will be deleted]" } else { app.replace_text.as_str() };
    f.render_widget(Paragraph::new(replace_content).block(replace_block), left_chunks[1]);

    // Result List
    let items: Vec<ListItem> = app.file_matches.iter().map(|fm| {
        ListItem::new(format!("{} ({})", fm.path.display(), fm.matches.len()))
    }).collect();
    let list_block = Block::default()
        .borders(Borders::ALL)
        .title("Result List")
        .border_style(if matches!(app.focused_pane, Pane::ResultList) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    f.render_stateful_widget(List::new(items).block(list_block).highlight_style(Style::default().bg(Color::Blue)), left_chunks[2], &mut app.list_state);

    // Preview
    let preview_block = Block::default()
        .borders(Borders::ALL)
        .title("Preview")
        .border_style(if matches!(app.focused_pane, Pane::Preview) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });

    let mut preview_lines = Vec::new();
    if let Some(selected) = app.list_state.selected() {
        if let Some(fm) = app.file_matches.get(selected) {
            for (i, m) in fm.matches.iter().enumerate() {
                if i > 0 {
                    preview_lines.push(Line::from(Span::styled("------------------------------------------------------", Style::default().fg(Color::Indexed(8)))));
                }

                let line_idx = m.line_number as i32 - 1;
                // Line before
                if line_idx > 0 {
                    let prev_line = &fm.lines[(line_idx - 1) as usize];
                    preview_lines.push(Line::from(vec![
                        Span::styled(format!("{:4} ", line_idx), Style::default().fg(Color::Blue)),
                        Span::styled(prev_line, Style::default().fg(Color::Indexed(8))),
                    ]));
                } else if selected > 0 {
                    // This is the weird bug where it shows line from previous file
                    let prev_fm = &app.file_matches[selected-1];
                    let prev_line = &prev_fm.lines[prev_fm.lines.len()-1];
                    preview_lines.push(Line::from(vec![
                        Span::styled(format!("{:4} ", 0), Style::default().fg(Color::Blue)),
                        Span::styled(prev_line, Style::default().fg(Color::Indexed(8))),
                    ]));
                }

                // Match line
                let mut match_spans = vec![
                    Span::styled(if app.expanded && i == app.match_index { ">" } else { " " }, Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                    Span::styled(format!("{:4} ", m.line_number), Style::default().fg(Color::Green)),
                ];

                let line = &m.line_content;
                let mut last_end = 0;
                // Note: technically there could be multiple matches on one line, but fm.matches stores them separately
                // So we only highlight the current match 'm' here.
                match_spans.push(Span::raw(&line[..m.start]));
                match_spans.push(Span::styled(&line[m.start..m.end], Style::default().bg(Color::Red).fg(Color::White).add_modifier(Modifier::CROSSED_OUT)));
                if !matches!(app.replace_mode, ReplaceMode::DeleteLine) {
                    match_spans.push(Span::styled(app.get_replacement(&line[m.start..m.end]), Style::default().bg(Color::Green).fg(Color::White)));
                }
                match_spans.push(Span::raw(&line[m.end..]));

                preview_lines.push(Line::from(match_spans));

                // Line after
                if (line_idx as usize) < fm.lines.len() - 1 {
                    let next_line = &fm.lines[(line_idx + 1) as usize];
                    preview_lines.push(Line::from(vec![
                        Span::styled(format!("{:4} ", line_idx + 2), Style::default().fg(Color::Blue)),
                        Span::styled(next_line, Style::default().fg(Color::Indexed(8))),
                    ]));
                }
            }
        }
    }

    f.render_widget(Paragraph::new(preview_lines).block(preview_block).wrap(Wrap { trim: false }), chunks[1]);

    // Help line
    let help_text = match app.focused_pane {
        Pane::Search => "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode:",
        Pane::Replace => "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode:",
        Pane::ResultList => "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r>",
        Pane::Preview => "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line:",
    };
    let help_line = Paragraph::new(help_text).style(Style::default().fg(Color::Blue));
    f.render_widget(help_line, Rect::new(0, f.size().height - 1, f.size().width, 1));

    // Notification
    if let Some((msg, _)) = &app.notification {
        let area = centered_rect(40, 10, f.size());
        f.render_widget(Clear, area);
        f.render_widget(Paragraph::new(msg.as_str()).block(Block::default().borders(Borders::ALL).title("Notification")), area);
    }

    // Help dialog
    if app.show_help {
        let area = centered_rect(60, 60, f.size());
        f.render_widget(Clear, area);
        let titles = vec!["[1] Global", "[2] Navigation"];
        let help_chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Length(3), Constraint::Min(0)].as_ref())
            .split(area);

        let tabs = Tabs::new(titles.iter().cloned().map(Line::from).collect())
            .select(app.help_tab)
            .block(Block::default().borders(Borders::ALL).title("Help dialog"))
            .highlight_style(Style::default().fg(Color::Yellow));
        f.render_widget(tabs, help_chunks[0]);

        let help_content = if app.help_tab == 0 {
            "- Ctrl-c: Quit\n- Ctrl-d: Quit\n- Ctrl-b: Help dialog\n- Ctrl-o: Process Replace For All Files\n- Ctrl-n: Loop through search and replace modes\n- Enter: Select/Deselect file\n- d: delete file/delete line from the replace process\n- r: Replace Selected File Or Line"
        } else {
            "- Tab: Loop through panes\n- j/UpArrow: Move up\n- k/DownArrow: Move down\n- h/g/LeftArrow: Move to Top\n- l/G/RightArrow: Move to Bottom"
        };
        f.render_widget(Paragraph::new(help_content).block(Block::default().borders(Borders::ALL)), help_chunks[1]);
    }

    // Confirmation dialog
    if app.show_confirm {
        let area = centered_rect(50, 20, f.size());
        f.render_widget(Clear, area);
        let confirm_block = Block::default().borders(Borders::ALL).title("Confirm Dialog");
        let confirm_text = "\n This action will modify the files in this directory.\n          Are you sure you want to continue?\n\n\n                   Continue  Cancel";
        f.render_widget(Paragraph::new(confirm_text).block(confirm_block), area);
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ].as_ref())
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ].as_ref())
        .split(popup_layout[1])[1]
}
