actions.command:
cat <<'EOF' > src/main.rs
use clap::Parser;
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Clear, List, ListItem, ListState, Paragraph, Wrap, Tabs},
    Frame, Terminal,
};
use std::{
    error::Error,
    fs,
    io,
    path::{Path, PathBuf},
};
use ignore::WalkBuilder;
use regex::RegexBuilder;

#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    #[arg(short = 'p', long, default_value = ".")]
    project_root: PathBuf,
}

#[derive(Copy, Clone, PartialEq, Debug)]
enum SearchMode {
    Simple,
    MatchCase,
    MatchWholeWord,
    MatchCaseWholeWord,
    Regex,
}

impl SearchMode {
    fn next(self) -> Self {
        match self {
            SearchMode::Simple => SearchMode::MatchCase,
            SearchMode::MatchCase => SearchMode::MatchWholeWord,
            SearchMode::MatchWholeWord => SearchMode::MatchCaseWholeWord,
            SearchMode::MatchCaseWholeWord => SearchMode::Regex,
            SearchMode::Regex => SearchMode::Simple,
        }
    }
    fn label(self) -> &'static str {
        match self {
            SearchMode::Simple => "Simple",
            SearchMode::MatchCase => "Match Case",
            SearchMode::MatchWholeWord => "Match Whole Word",
            SearchMode::MatchCaseWholeWord => "Match Case Whole Word",
            SearchMode::Regex => "Regex",
        }
    }
}

#[derive(Copy, Clone, PartialEq, Debug)]
enum ReplaceMode {
    Simple,
    PreserveCase,
    DeleteLine,
}

impl ReplaceMode {
    fn next(self) -> Self {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }
    fn label(self) -> &'static str {
        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }
}

#[derive(Debug, Clone)]
struct Match {
    line_number: usize,
    line_content: String,
    start: usize,
    end: usize,
}

#[derive(Debug, Clone)]
struct FileMatches {
    path: PathBuf,
    matches: Vec<Match>,
    lines: Vec<String>,
}

enum Pane {
    Search,
    Replace,
    ResultList,
    Preview,
}

struct App {
    project_root: PathBuf,
    search_text: String,
    replace_text: String,
    search_mode: SearchMode,
    replace_mode: ReplaceMode,
    focused_pane: Pane,
    file_matches: Vec<FileMatches>,
    list_state: ListState,
    expanded: bool,
    match_index: usize, // Index of selected match in expanded view
    show_help: bool,
    help_tab: usize,
    show_confirm: bool,
    confirm_index: usize,
    notification: Option<(String, std::time::Instant)>,
}

impl App {
    fn new(project_root: PathBuf) -> App {
        App {
            project_root,
            search_text: String::new(),
            replace_text: String::new(),
            search_mode: SearchMode::Simple,
            replace_mode: ReplaceMode::Simple,
            focused_pane: Pane::Search,
            file_matches: Vec::new(),
            list_state: ListState::default(),
            expanded: false,
            match_index: 0,
            show_help: false,
            help_tab: 0,
            show_confirm: false,
            confirm_index: 0,
            notification: None,
        }
    }

    fn update_search(&mut self) {
        if self.search_text.is_empty() {
            self.file_matches.clear();
            self.list_state.select(None);
            return;
        }

        let mut results = Vec::new();
        let walk = WalkBuilder::new(&self.project_root)
            .hidden(true)
            .git_ignore(true)
            .build();

        for entry in walk.filter_map(|e| e.ok()) {
            if entry.file_type().map(|ft| ft.is_file()).unwrap_or(false) {
                if let Ok(content) = fs::read_to_string(entry.path()) {
                    let mut matches = Vec::new();
                    let lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
                    for (i, line) in lines.iter().enumerate() {
                        let line_matches = self.find_matches(line);
                        for (start, end) in line_matches {
                            matches.push(Match {
                                line_number: i + 1,
                                line_content: line.clone(),
                                start,
                                end,
                            });
                        }
                    }
                    if !matches.is_empty() {
                        results.push(FileMatches {
                            path: entry.path().strip_prefix(&self.project_root).unwrap_or(entry.path()).to_path_buf(),
                            matches,
                            lines,
                        });
                    }
                }
            }
        }
        self.file_matches = results;
        if self.list_state.selected().is_none() && !self.file_matches.is_empty() {
            self.list_state.select(Some(0));
        } else if let Some(selected) = self.list_state.selected() {
            if selected >= self.file_matches.len() {
                if self.file_matches.is_empty() {
                    self.list_state.select(None);
                } else {
                    self.list_state.select(Some(self.file_matches.len() - 1));
                }
            }
        }
    }

    fn find_matches(&self, line: &str) -> Vec<(usize, usize)> {
        let mut results = Vec::new();
        match self.search_mode {
            SearchMode::Regex => {
                let mut builder = RegexBuilder::new(&self.search_text);
                builder.case_insensitive(true);
                if let Ok(re) = builder.build() {
                    for m in re.find_iter(line) {
                        results.push((m.start(), m.end()));
                    }
                }
            }
            _ => {
                let case_sensitive = matches!(self.search_mode, SearchMode::MatchCase | SearchMode::MatchCaseWholeWord);
                let whole_word = matches!(self.search_mode, SearchMode::MatchWholeWord | SearchMode::MatchCaseWholeWord);

                let search_pattern = if case_sensitive { self.search_text.clone() } else { self.search_text.to_lowercase() };
                let target_line = if case_sensitive { line.to_string() } else { line.to_lowercase() };

                let mut start = 0;
                while let Some(pos) = target_line[start..].find(&search_pattern) {
                    let actual_start = start + pos;
                    let actual_end = actual_start + search_pattern.len();

                    let mut is_match = true;
                    if whole_word {
                        let prev_is_word = if actual_start > 0 {
                            let c = line.chars().nth(actual_start - 1).unwrap();
                            c.is_alphanumeric() || c == '_'
                        } else { false };
                        let next_is_word = if actual_end < line.len() {
                            let c = line.chars().nth(actual_end).unwrap();
                            c.is_alphanumeric() || c == '_'
                        } else { false };
                        if prev_is_word || next_is_word {
                            is_match = false;
                        }
                    }

                    if is_match {
                        results.push((actual_start, actual_end));
                    }
                    if search_pattern.is_empty() { break; }
                    start = actual_start + 1.max(search_pattern.len());
                }
            }
        }
        results
    }

    fn perform_replace_all(&mut self) {
        if self.search_text.is_empty() {
            self.set_notification("Search text cannot be empty");
            return;
        }
        // Actually we should perform it on all files
        let files_to_modify: Vec<_> = self.file_matches.iter().map(|fm| fm.path.clone()).collect();
        for path in files_to_modify {
            self.replace_in_file(&path);
        }
        self.update_search();
        self.set_notification("Replacement completed successfully");
    }

    fn replace_in_file(&self, rel_path: &Path) {
        let full_path = self.project_root.join(rel_path);
        if let Ok(content) = fs::read_to_string(&full_path) {
            let mut new_lines = Vec::new();
            for line in content.lines() {
                if matches!(self.replace_mode, ReplaceMode::DeleteLine) {
                    if !self.find_matches(line).is_empty() {
                        continue;
                    }
                    new_lines.push(line.to_string());
                } else {
                    new_lines.push(self.replace_line(line));
                }
            }
            let _ = fs::write(full_path, new_lines.join("\n") + if content.ends_with('\n') { "\n" } else { "" });
        }
    }

    fn replace_line(&self, line: &str) -> String {
        let matches = self.find_matches(line);
        if matches.is_empty() {
            return line.to_string();
        }
        let mut new_line = String::new();
        let mut last_end = 0;
        for (start, end) in matches {
            new_line.push_str(&line[last_end..start]);
            let original = &line[start..end];
            let replacement = self.get_replacement(original);
            new_line.push_str(&replacement);
            last_end = end;
        }
        new_line.push_str(&line[last_end..]);
        new_line
    }

    fn get_replacement(&self, original: &str) -> String {
        match self.replace_mode {
            ReplaceMode::Simple => self.replace_text.clone(),
            ReplaceMode::PreserveCase => {
                if original.chars().all(|c| c.is_uppercase() && c.is_alphabetic()) {
                    self.replace_text.to_uppercase()
                } else if original.chars().next().map(|c| c.is_uppercase()).unwrap_or(false) {
                    let mut chars = self.replace_text.chars();
                    match chars.next() {
                        Some(f) => f.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase(),
                        None => String::new(),
                    }
                } else {
                    self.replace_text.to_lowercase()
                }
            }
            ReplaceMode::DeleteLine => String::new(),
        }
    }

    fn set_notification(&mut self, msg: &str) {
        self.notification = Some((msg.to_string(), std::time::Instant::now()));
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let args = Args::parse();
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(args.project_root);
    let res = run_app(&mut terminal, app);

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        println!("{:?}", err);
    }

    Ok(())
}

fn run_app<B: Backend>(terminal: &mut Terminal<B>, mut app: App) -> io::Result<()> {
    loop {
        if let Some((_, time)) = &app.notification {
            if time.elapsed().as_secs() > 3 {
                app.notification = None;
            }
        }

        terminal.draw(|f| ui(f, &mut app))?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if app.show_help {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => app.show_help = false,
                        KeyCode::Right => app.help_tab = (app.help_tab + 1) % 2,
                        KeyCode::Left => app.help_tab = (app.help_tab + 1) % 2,
                        _ => {}
                    }
                    continue;
                }
                if app.show_confirm {
                    match key.code {
                        KeyCode::Enter => {
                            app.perform_replace_all();
                            app.show_confirm = false;
                        }
                        KeyCode::Esc | KeyCode::Left | KeyCode::Char('q') => app.show_confirm = false,
                        _ => {}
                    }
                    continue;
                }

                match key.code {
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return Ok(()),
                    KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => return Ok(()),
                    KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => app.show_help = true,
                    KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        match app.focused_pane {
                            Pane::Search => { app.search_mode = app.search_mode.next(); app.update_search(); }
                            Pane::Replace => { app.replace_mode = app.replace_mode.next(); }
                            _ => {}
                        }
                    }
                    KeyCode::Char('o') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        if app.search_text.is_empty() {
                            app.set_notification("Search text cannot be empty");
                        } else {
                            app.show_confirm = true;
                        }
                    }
                    KeyCode::Tab => {
                        if !app.expanded {
                            app.focused_pane = match app.focused_pane {
                                Pane::Search => Pane::Replace,
                                Pane::Replace => Pane::ResultList,
                                Pane::ResultList => Pane::Search,
                                Pane::Preview => Pane::Search,
                            };
                        }
                    }
                    KeyCode::Enter => {
                        match app.focused_pane {
                            Pane::ResultList => {
                                if !app.expanded {
                                    if !app.file_matches.is_empty() {
                                        app.expanded = true;
                                        app.focused_pane = Pane::Preview;
                                        app.match_index = 0;
                                    }
                                } else {
                                    app.expanded = false;
                                    app.focused_pane = Pane::ResultList;
                                }
                            }
                            _ => {}
                        }
                    }
                    KeyCode::Up | KeyCode::Char('j') => {
                        match app.focused_pane {
                            Pane::ResultList => {
                                let i = match app.list_state.selected() {
                                    Some(i) => if i == 0 { app.file_matches.len() - 1 } else { i - 1 },
                                    None => 0,
                                };
                                app.list_state.select(Some(i));
                            }
                            Pane::Preview => {
                                if let Some(fm) = app.file_matches.get(app.list_state.selected().unwrap_or(0)) {
                                    if app.match_index == 0 {
                                        app.match_index = fm.matches.len() - 1;
                                    } else {
                                        app.match_index -= 1;
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                    KeyCode::Down | KeyCode::Char('k') => {
                        match app.focused_pane {
                            Pane::ResultList => {
                                let i = match app.list_state.selected() {
                                    Some(i) => if i >= app.file_matches.len() - 1 { 0 } else { i + 1 },
                                    None => 0,
                                };
                                app.list_state.select(Some(i));
                            }
                            Pane::Preview => {
                                if let Some(fm) = app.file_matches.get(app.list_state.selected().unwrap_or(0)) {
                                    if app.match_index >= fm.matches.len() - 1 {
                                        app.match_index = 0;
                                    } else {
                                        app.match_index += 1;
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                    KeyCode::Char('r') => {
                        if !app.file_matches.is_empty() {
                            if app.expanded {
                                if let Some(selected) = app.list_state.selected() {
                                    let fm = &app.file_matches[selected];
                                    let mat = &fm.matches[app.match_index];
                                    let full_path = app.project_root.join(&fm.path);
                                    let content = fs::read_to_string(&full_path).unwrap();
                                    let mut lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
                                    let line_idx = mat.line_number - 1;
                                    if matches!(app.replace_mode, ReplaceMode::DeleteLine) {
                                        lines.remove(line_idx);
                                    } else {
                                        lines[line_idx] = app.replace_line(&lines[line_idx]);
                                    }
                                    let _ = fs::write(full_path, lines.join("\n") + if content.ends_with('\n') { "\n" } else { "" });
                                    app.update_search();
                                    app.set_notification("Line replacement completed successfully");
                                }
                            } else {
                                if let Some(selected) = app.list_state.selected() {
                                    app.replace_in_file(&app.file_matches[selected].path.clone());
                                    app.update_search();
                                    app.set_notification("File replacement completed successfully");
                                }
                            }
                        }
                    }
                    KeyCode::Char(c) => {
                        match app.focused_pane {
                            Pane::Search => { app.search_text.push(c); app.update_search(); }
                            Pane::Replace => { app.replace_text.push(c); }
                            _ => {}
                        }
                    }
                    KeyCode::Backspace => {
                        match app.focused_pane {
                            Pane::Search => { app.search_text.pop(); app.update_search(); }
                            Pane::Replace => { app.replace_text.pop(); }
                            _ => {}
                        }
                    }
                    KeyCode::Esc => {
                        if app.expanded {
                            app.expanded = false;
                            app.focused_pane = Pane::ResultList;
                        }
                    }
                    _ => {}
                }
            }
        }
    }
}

fn ui(f: &mut Frame, app: &mut App) {
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(30), Constraint::Percentage(70)].as_ref())
        .split(f.size());

    let left_chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Min(0),
        ].as_ref())
        .split(chunks[0]);

    // Search box
    let search_block = Block::default()
        .borders(Borders::ALL)
        .title(format!("Search [{}]", app.search_mode.label()))
        .border_style(if matches!(app.focused_pane, Pane::Search) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    f.render_widget(Paragraph::new(app.search_text.as_str()).block(search_block), left_chunks[0]);

    // Replace box
    let replace_block = Block::default()
        .borders(Borders::ALL)
        .title(format!("Replace [{}]", app.replace_mode.label()))
        .border_style(if matches!(app.focused_pane, Pane::Replace) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    let replace_content = if matches!(app.replace_mode, ReplaceMode::DeleteLine) { "[Entire line will be deleted]" } else { app.replace_text.as_str() };
    f.render_widget(Paragraph::new(replace_content).block(replace_block), left_chunks[1]);

    // Result List
    let items: Vec<ListItem> = app.file_matches.iter().map(|fm| {
        ListItem::new(format!("{} ({})", fm.path.display(), fm.matches.len()))
    }).collect();
    let list_block = Block::default()
        .borders(Borders::ALL)
        .title("Result List")
        .border_style(if matches!(app.focused_pane, Pane::ResultList) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });
    f.render_stateful_widget(List::new(items).block(list_block).highlight_style(Style::default().bg(Color::Blue)), left_chunks[2], &mut app.list_state);

    // Preview
    let preview_block = Block::default()
        .borders(Borders::ALL)
        .title("Preview")
        .border_style(if matches!(app.focused_pane, Pane::Preview) { Style::default().fg(Color::Green) } else { Style::default().fg(Color::White) });

    let mut preview_lines = Vec::new();
    if let Some(selected) = app.list_state.selected() {
        if let Some(fm) = app.file_matches.get(selected) {
            for (i, m) in fm.matches.iter().enumerate() {
                if i > 0 {
                    preview_lines.push(Line::from(Span::styled("------------------------------------------------------", Style::default().fg(Color::Indexed(8)))));
                }

                let line_idx = m.line_number as i32 - 1;
                // Line before
                if line_idx > 0 {
                    let prev_line = &fm.lines[(line_idx - 1) as usize];
                    preview_lines.push(Line::from(vec![
                        Span::styled(format!("{:4} ", line_idx), Style::default().fg(Color::Blue)),
                        Span::styled(prev_line, Style::default().fg(Color::Indexed(8))),
                    ]));
                } else if selected > 0 {
                    // This is the weird bug where it shows line from previous file
                    let prev_fm = &app.file_matches[selected-1];
                    let prev_line = &prev_fm.lines[prev_fm.lines.len()-1];
                    preview_lines.push(Line::from(vec![
                        Span::styled(format!("{:4} ", 0), Style::default().fg(Color::Blue)),
                        Span::styled(prev_line, Style::default().fg(Color::Indexed(8))),
                    ]));
                }

                // Match line
                let mut match_spans = vec![
                    Span::styled(if app.expanded && i == app.match_index { ">" } else { " " }, Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
                    Span::styled(format!("{:4} ", m.line_number), Style::default().fg(Color::Green)),
                ];

                let line = &m.line_content;
                let mut last_end = 0;
                // Note: technically there could be multiple matches on one line, but fm.matches stores them separately
                // So we only highlight the current match 'm' here.
                match_spans.push(Span::raw(&line[..m.start]));
                match_spans.push(Span::styled(&line[m.start..m.end], Style::default().bg(Color::Red).fg(Color::White).add_modifier(Modifier::CROSSED_OUT)));
                if !matches!(app.replace_mode, ReplaceMode::DeleteLine) {
                    match_spans.push(Span::styled(app.get_replacement(&line[m.start..m.end]), Style::default().bg(Color::Green).fg(Color::White)));
                }
                match_spans.push(Span::raw(&line[m.end..]));

                preview_lines.push(Line::from(match_spans));

                // Line after
                if (line_idx as usize) < fm.lines.len() - 1 {
                    let next_line = &fm.lines[(line_idx + 1) as usize];
                    preview_lines.push(Line::from(vec![
                        Span::styled(format!("{:4} ", line_idx + 2), Style::default().fg(Color::Blue)),
                        Span::styled(next_line, Style::default().fg(Color::Indexed(8))),
                    ]));
                }
            }
        }
    }

    f.render_widget(Paragraph::new(preview_lines).block(preview_block).wrap(Wrap { trim: false }), chunks[1]);

    // Help line
    let help_text = match app.focused_pane {
        Pane::Search => "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode:",
        Pane::Replace => "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode:",
        Pane::ResultList => "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r>",
        Pane::Preview => "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line:",
    };
    let help_line = Paragraph::new(help_text).style(Style::default().fg(Color::Blue));
    f.render_widget(help_line, Rect::new(0, f.size().height - 1, f.size().width, 1));

    // Notification
    if let Some((msg, _)) = &app.notification {
        let area = centered_rect(40, 10, f.size());
        f.render_widget(Clear, area);
        f.render_widget(Paragraph::new(msg.as_str()).block(Block::default().borders(Borders::ALL).title("Notification")), area);
    }

    // Help dialog
    if app.show_help {
        let area = centered_rect(60, 60, f.size());
        f.render_widget(Clear, area);
        let titles = vec!["[1] Global", "[2] Navigation"];
        let help_chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Length(3), Constraint::Min(0)].as_ref())
            .split(area);

        let tabs = Tabs::new(titles.iter().cloned().map(Line::from).collect())
            .select(app.help_tab)
            .block(Block::default().borders(Borders::ALL).title("Help dialog"))
            .highlight_style(Style::default().fg(Color::Yellow));
        f.render_widget(tabs, help_chunks[0]);

        let help_content = if app.help_tab == 0 {
            "- Ctrl-c: Quit\n- Ctrl-d: Quit\n- Ctrl-b: Help dialog\n- Ctrl-o: Process Replace For All Files\n- Ctrl-n: Loop through search and replace modes\n- Enter: Select/Deselect file\n- d: delete file/delete line from the replace process\n- r: Replace Selected File Or Line"
        } else {
            "- Tab: Loop through panes\n- j/UpArrow: Move up\n- k/DownArrow: Move down\n- h/g/LeftArrow: Move to Top\n- l/G/RightArrow: Move to Bottom"
        };
        f.render_widget(Paragraph::new(help_content).block(Block::default().borders(Borders::ALL)), help_chunks[1]);
    }

    // Confirmation dialog
    if app.show_confirm {
        let area = centered_rect(50, 20, f.size());
        f.render_widget(Clear, area);
        let confirm_block = Block::default().borders(Borders::ALL).title("Confirm Dialog");
        let confirm_text = "\n This action will modify the files in this directory.\n          Are you sure you want to continue?\n\n\n                   Continue  Cancel";
        f.render_widget(Paragraph::new(confirm_text).block(confirm_block), area);
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ].as_ref())
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ].as_ref())
        .split(popup_layout[1])[1]
}
